style:
/* 橙意 —— 圆形头像、橙色左条标题，内容收进浅框 */

.tw-chengyi.layout-profile.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 0;
  border-bottom: none;
  align-items: center;
  gap: 7mm;
}

.tw-chengyi.layout-profile.resume-paper .paper-photo {
  order: -1;
  width: 26mm;
  height: 26mm;
  border: 1.4mm solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 0.3mm #f3ddcb;
  object-fit: cover;
}

.tw-chengyi.layout-profile.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fdf3ec;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.9);
  font-weight: 700;
}

.tw-chengyi.layout-profile.resume-paper .paper-name {
  color: #242424;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.04em;
}

.tw-chengyi.layout-profile.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #8a8a8a;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-chengyi.layout-profile.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #5c5c5c;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-chengyi.layout-profile.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 5mm;
  margin-top: 3mm;
  color: #4a4a4a;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-chengyi.layout-profile.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-chengyi.layout-profile.resume-paper .paper-contact + .paper-contact::before {
  content: "";
  left: -2.6mm;
  width: 0.2mm;
  height: 3.2mm;
  background: #e6e6e6;
  print-color-adjust: exact;
}

.tw-chengyi.layout-profile.resume-paper .paper-contact__label {
  color: #929292;
}

/* 标题：橙色竖条 + 深色标题 */
.tw-chengyi.layout-profile.resume-paper .paper-section__title {
  position: relative;
  margin-bottom: 2.6mm;
  padding-left: 4.4mm;
  border-bottom: none;
  color: #242424;
  font-size: calc(var(--paper-base-size) * 1.08);
  letter-spacing: 0.04em;
}

.tw-chengyi.layout-profile.resume-paper .paper-section__title::before {
  content: "";
  position: absolute;
  top: 0.5mm;
  left: 0;
  width: 1.4mm;
  height: 4.8mm;
  background: var(--paper-accent);
  print-color-adjust: exact;
}

.tw-chengyi.layout-profile.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

/* 内容收进浅灰细框，框内留一点气口 */
.tw-chengyi.layout-profile.resume-paper .paper-section__body {
  padding: 3mm 3.4mm;
  border: 0.22mm solid #efe7e1;
  color: #3a3a3a;
}

.tw-chengyi.layout-profile.resume-paper .paper-item + .paper-item {
  margin-top: 2.4mm;
}

.tw-chengyi.layout-profile.resume-paper .paper-item-title {
  color: #242424;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-chengyi.layout-profile.resume-paper .paper-item-period {
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 0.86);
  font-weight: 600;
}

.tw-chengyi.layout-profile.resume-paper .paper-item-sub {
  gap: 0;
  color: #4a4a4a;
}

.tw-chengyi.layout-profile.resume-paper .paper-item-sub span + span::before {
  content: "";
  margin-right: 6mm;
}

/* 技能：三列进度条，名称在上、熟练度在下 */
.tw-chengyi.layout-profile.resume-paper .paper-skills {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2mm 7mm;
}

.tw-chengyi.layout-profile.resume-paper .paper-skill {
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-chengyi.layout-profile.resume-paper .paper-skill__name {
  display: block;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-chengyi.layout-profile.resume-paper .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 1.2mm;
}

.tw-chengyi.layout-profile.resume-paper .paper-skill__dots i {
  width: 100%;
  height: 1.8mm;
  border-radius: 0;
  background: #f0e6de;
}

.tw-chengyi.layout-profile.resume-paper .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-chengyi.layout-profile.resume-paper .paper-skill__level {
  display: block;
  margin-top: 1mm;
  color: #7a7a7a;
  font-size: calc(var(--paper-base-size) * 0.8);
}

.tw-chengyi.layout-profile.resume-paper .paper-rich ul,
.tw-chengyi.layout-profile.resume-paper .paper-rich ol {
  margin-top: 0;
  padding-left: 1.1em;
}

.tw-chengyi.layout-profile.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

.tw-chengyi.layout-profile.resume-paper .paper-note__tag {
  display: inline;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  color: #242424;
  font-weight: 600;
}

.tw-chengyi.layout-profile.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-chengyi.layout-profile.resume-paper .paper-note {
  color: #6a6a6a;
}

.tw-chengyi.layout-profile.resume-paper .paper-footer {
  border-top: 0.2mm solid #f0e8e2;
  color: #a8a8a8;
}
